```java
// BEFORE authentication — unauthenticated (used during login)
UsernamePasswordAuthenticationToken unauthenticated =
    new UsernamePasswordAuthenticationToken(username, password);
// isAuthenticated() == false

// AFTER authentication — authenticated (Spring Security creates this)
UsernamePasswordAuthenticationToken authenticated =
    new UsernamePasswordAuthenticationToken(userDetails, null, authorities);
// isAuthenticated() == true

// In JWT filter — manually create authenticated token:
SecurityContextHolder.getContext().setAuthentication(
    new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities())
);
```

```java
// Form Login — browser-based, session-based:
http.formLogin(Customizer.withDefaults())
// → unauthenticated request → redirect to /login
// → POST /login → session created → browser stores cookie

// HTTP Basic — credential in every request:
http.httpBasic(Customizer.withDefaults())
// → unauthenticated request → 401 with WWW-Authenticate: Basic realm='...' header
// → client sends: Authorization: Basic base64(username:password)
// → server validates on every request — no session

// In curl:
// curl -u alice:password http://localhost:8080/api/data
```
